import re,html,json,random,collections,itertools,statistics,hashlib
from vs import corpus,ivtff
from functools import lru_cache
from pathlib import Path
reg=json.load(open('/tmp/p-g-024.json'))['detail']['evidence'];fit=reg['frozen_fit'];banks=fit['schedule'];pbank=fit['exception_bank_draw_probability']
src=html.unescape(re.sub(r'<[^>]+>','',Path('/tmp/stolfi-grammar.html').read_text()))
src=src[src.index('NormalWord:'):src.index('AbnormalWord:')]
gram={};cur=None
for line in src.splitlines():
 m=re.match(r'^([A-Za-z][A-Za-z0-9]*):\s*$',line)
 if m:cur=m[1];gram[cur]=[];continue
 m=re.match(r'^\s*\d+\s+[\d.]+\s+[\d.]+\s+(\S+)',line)
 if m and cur:gram[cur].append(m[1])
@lru_cache(None)
def pattern(n):
 if n not in gram:return re.escape(n)
 return '(?:'+'|'.join(''.join(pattern(x) for x in alt.split('.') if x) for alt in gram[n])+')'
normal=re.compile('^'+pattern('NormalWord')+'$')
def eligible(w):return bool(re.fullmatch('[a-z]+',w))
def sequences(pages):
 seq=[]
 for page in pages:
  for line in page.lines:
   if line.unit!='P':continue
   part=[]
   for w in line.words:
    if eligible(w):part.append(w)
    elif part:seq.append(part);part=[]
   if part:seq.append(part)
 return seq
def glen(w):return len(ivtff.segment(w,'eva-basic'))
def edit1(a,b):
 a=ivtff.segment(a,'eva-basic');b=ivtff.segment(b,'eva-basic')
 if abs(len(a)-len(b))>1:return False
 if len(a)==len(b):return sum(x!=y for x,y in zip(a,b))==1
 if len(a)>len(b):a,b=b,a
 i=0
 while i<len(a) and a[i]==b[i]:i+=1
 return a[i:]==b[i+1:]
def tv(a,b):
 aa=sum(a.values());bb=sum(b.values());return sum(abs(a.get(k,0)/aa-b.get(k,0)/bb) for k in set(a)|set(b))/2
train,_=corpus.split_pages('practice');tr=[w for seq in sequences(train) for w in seq]; trset=set(tr)
# Freeze: fit only ZL training length ratios; clip inverse-frequency weights to [0.25,4],
# shared fragment probability 0.10, same bank/role only, uniform if no previous slot;
# independent random draw 0.0531926 specialist; seed 31001-31010.
triples={};hist=collections.Counter()
for b,slots in banks.items():
 triples[b]=[(tuple(t),' '.join([]).join(sum((list(x) for x in t),[]))) for t in itertools.product(*slots)]
 for t,w in triples[b]:hist[glen(w)]+=(pbank if b=='exception_bank' else 1-pbank)/len(triples[b])
target=collections.Counter(map(glen,tr));total=sum(target.values())
weights={n:min(4,max(.25,(target[n]/total)/v)) for n,v in hist.items() if v}
print('training',len(tr),'abnormal',sum(not bool(normal.fullmatch(w)) for w in tr)/len(tr),'weights',weights,flush=True)
support={w for t in triples.values() for _,w in t};ab_unseen={w for w in support if w not in trset and not normal.fullmatch(w)}
print('support',len(support),'abnormal-unseen',len(ab_unseen),flush=True)
for trans in ('zl','it'):
 _,ev=corpus.split_pages('practice',trans); seqs=sequences(ev); real=[w for seq in seqs for w in seq]; pairs=[(a,b) for seq in seqs for a,b in zip(seq,seq[1:])]; bylen=collections.defaultdict(list)
 for w in real:bylen[glen(w)].append(w)
 realpairs=[(a,b) for a,b in pairs if glen(a) in hist and glen(b) in hist]
 print('real',trans,len(real),len(pairs),'abnormal',sum(not bool(normal.fullmatch(w)) for w in real)/len(real),'repeat',sum(a==b for a,b in realpairs)/len(realpairs),'edit1',sum(edit1(a,b) for a,b in realpairs)/len(realpairs),'coverage',len({w for w in real if not normal.fullmatch(w) and w not in trset}&support),flush=True)
 for weighted in (False,True):
  for share in (False,True):
   results=[]
   for seed in range(31001,31011):
    rng=random.Random(seed); generated=[];gp=[]; prev=None
    dist={b:list(itertools.accumulate(weights[glen(w)] if weighted else 1 for t,w in vals)) for b,vals in triples.items()}
    for seq in seqs:
     oldw=None;prev=None
     for _ in seq:
      bank='exception_bank' if rng.random()<pbank else 'baseline'; ts=triples[bank];ix=rng.choices(range(len(ts)),cum_weights=dist[bank],k=1)[0];t=list(ts[ix][0]);
      if share and prev and prev[0]==bank and rng.random()<.1:
       role=rng.randrange(3);t[role]=prev[1][role]
      w=''.join(sum((list(f) for f in t),[]));generated.append(w)
      if oldw is not None:gp.append((oldw,w))
      oldw=w;prev=(bank,t)
    strata=collections.defaultdict(list)
    for a,b in gp:strata[(glen(a),glen(b))].append((a,b))
    rp=[(a,b) for a,b in realpairs if (glen(a),glen(b)) in strata]
    matched=[rng.choice(strata[(glen(a),glen(b))]) for a,b in rp]
    realind=[(rng.choice(bylen[glen(a)]),rng.choice(bylen[glen(b)])) for a,b in rp]
    results.append({'token_tv':tv(collections.Counter(map(glen,real)),collections.Counter(map(glen,generated))),'type_tv':tv(collections.Counter(map(glen,set(real))),collections.Counter(map(glen,set(generated)))),'repeat':sum(a==b for a,b in gp)/len(gp),'edit1':sum(edit1(a,b) for a,b in gp)/len(gp),'abnormal':sum(not bool(normal.fullmatch(w)) for w in generated)/len(generated),'support':len(rp)/len(realpairs),'matched_real_repeat':sum(a==b for a,b in rp)/len(rp),'matched_real_edit1':sum(edit1(a,b) for a,b in rp)/len(rp),'matched_repeat':sum(a==b for a,b in matched)/len(matched),'matched_edit1':sum(edit1(a,b) for a,b in matched)/len(matched),'iid_repeat':sum(a==b for a,b in realind)/len(realind),'iid_edit1':sum(edit1(a,b) for a,b in realind)/len(realind)})
   print('model',trans,weighted,share,json.dumps({k:round(statistics.median(x[k] for x in results),6) for k in results[0]}),flush=True)
